#!/usr/bin/env bash
# generate-ci-lockstep.sh — regenerate the classifier's lockstep list from
# specs/ci-docs-lockstep-paths.txt, the single source of truth for docs-set
# files whose content is an asserted Go test input. To change the list, edit
# the manifest (one repo-root-relative path per line, sorted) and re-run this
# script; never hand-edit the generated file. TestLockstepPathsMatchManifest
# pins the generated copy to the manifest, so a manifest edit without a
# re-run fails the build the same way a stale hand copy did.
#
# Every body this script emits is built with printf, never a heredoc, so it
# cannot hit the bash >=5.1 heredoc-pipe deadlock (#5019/#5074).
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
manifest="${repo_root}/specs/ci-docs-lockstep-paths.txt"
output="${repo_root}/go/internal/cigates/lockstep_manifest_generated.go"

entries=()
while IFS= read -r line || [ -n "$line" ]; do
	trimmed="${line#"${line%%[![:space:]]*}"}"
	trimmed="${trimmed%"${trimmed##*[![:space:]]}"}"
	case "$trimmed" in
		'' | \#*)
			continue
			;;
		*\"* | *\`* | *\\*)
			printf 'generate-ci-lockstep: entry %q is not a plain path\n' "$trimmed" >&2
			exit 1
			;;
	esac
	entries+=("$trimmed")
done <"$manifest"

if [ "${#entries[@]}" -eq 0 ]; then
	printf 'generate-ci-lockstep: manifest %s holds no paths\n' "$manifest" >&2
	exit 1
fi

{
	printf '// SPDX-License-Identifier: MIT\n'
	printf '// Copyright (c) 2025-2026 eshu-hq\n'
	printf '\n'
	printf '// Code generated by scripts/generate-ci-lockstep.sh from\n'
	printf '// specs/ci-docs-lockstep-paths.txt. DO NOT EDIT: edit the manifest\n'
	printf '// and re-run this script. TestLockstepPathsMatchManifest pins this\n'
	printf '// copy to the manifest.\n'
	printf '\n'
	printf 'package cigates\n'
	printf '\n'
	printf '// lockstepDocsPaths are docs-set-shaped files whose content is an\n'
	printf '// asserted Go test input (family tables, exported surfaces, doc\n'
	printf '// fences, runbooks, evidence JSON). Editing one can break a unit\n'
	printf '// test, so they stay code in every selection layer. Generated from\n'
	printf '// the canonical manifest; see the banner above.\n'
	printf 'var lockstepDocsPaths = []string{\n'
	for entry in "${entries[@]}"; do
		printf '\t"%s",\n' "$entry"
	done
	printf '}\n'
} >"$output"

printf 'generate-ci-lockstep: wrote %d entries to %s\n' "${#entries[@]}" "$output"
